module fsm_3state (
    input clk, reset,
    output [1:0] state
);
  reg [1:0] state_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state_reg <= 2'd0;
    end else begin
      case (state_reg)
        2'd0: state_reg <= 2'd1;
        2'd1: state_reg <= 2'd2;
        2'd2: state_reg <= 2'd0;
        default: state_reg <= 2'd0;
      endcase
    end
  end

  assign state = state_reg;

endmodule

module traffic_light (
    input clk, reset,
    output {light}
);

always @(posedge clk or posedge reset) begin
    if (reset)
        light <= 0;
    else
        case (light)
            2'b00: light <= 3;
            3: light <= 2'b10;
            2'b10: light <= 1;
            1: light <= 0;
            default: light <= 3;
        endcase
end

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output reg [1:0] state
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: // Idle
                if (up_request) state <= 2'b01;
                else if (down_request) state <= 2'b10;
                else state <= 2'b00;
                break;
            2'b01: // Moving Up
                if (down_request) state <= 2'b10;
                else state <= 2'b00;
                break;
            2'b10: // Moving Down
                if (up_request) state <= 2'b01;
                else state <= 2'b00;
                break;
            2'b11: // Error
                state <= 2'b00;
                break;
            default:
                state <= 2'b00;
                break;
        endcase
    end
end

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] state_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state_reg <= 2'b00;
    end else begin
        state_reg <= state;
    end
end

typedef enum register: state:
    INITIAL: (0),
    WORKING: (1),
    SWAPPING: (2),
    PURGING: (3),
    BREAKDOWN: (4),
    EMPTY: (5)
ENDDEF

always @(state_reg or item_selected or coin_inserted) begin
    case (state_reg)
        INITIAL:
            if (coin_inserted)
                state <= WORKING;
            else if (item_selected)
                state_breakdown;
            else
                state <= INITIAL;
        WORKING:
            if (item_selected)
                state <= SWAPPING;
            else if (coin_inserted)
                state <= INITIAL;
            else
                state <= WORKING;
        SWAPPING:
            if (item_selected)
                state <= PURGING;
            else if (coin_inserted)
                state <= INITIAL;
            else
                state <= SWAPPING;
        PURGING:
            if (item_selected)
                state <= BREAKDOWN;
            else if (coin_inserted)
                state <= INITIAL;
            else
                state <= PURGING;
        BREAKDOWN:
            if (coin_inserted)
                state <= EMPTY;
            else
                state <= BREAKDOWN;
        EMPTY:
            if (coin_inserted)
                state <= EMPTY;
            else
                state <= EMPTY;
        default:
            state <= INITIAL;
    endcase
end

