module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

always @(*) begin
    if (shift <= 1)
        out = in << shift;
    else if (shift <= 8)
        out = in << shift;
    else
        out = in;
end

endmodule

