module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
reg [31:0] register;
reg [1:0] shift_amount;

always @(in or shift)
    if (shift < 2)
        register <= in << shift;
    else
        register <= in >> (8 - shift);
end

always @*
    out <= register[7:4];

endmodule

