module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

integer lsb;
wire[7:0] next_gray, temp_gray;

logic [15:0] cnt;

always @(posedge clk or posedge rst)
    if(rst == 1'b1) cnt <= 0;
    else cnt <= cnt + 1;

assign next_gray = cnt;
assign count[0] = next_gray[0];
assign count[1] = next_gray[0] ^ next_gray[1];
assign count[2] = temp_gray;
assign count[3] = next_gray[0] ^ temp_gray[0] ^ next_gray[1];
assign count[4] = temp_gray[0] ^ temp_gray[2] ^ temp_gray[3];
assign count[5] = temp_gray[3] ^ temp_gray[4] ^ next_gray[2];
assign count[6] = temp_gray[4] ^ next_gray[0] ^ next_gray[5] ^ temp_gray[5];
assign temp_gray[0] = next_gray[6];
assign temp_gray[1] = next_gray[0] ^ next_gray[7];
assign temp_gray[2] = next_gray[0] ^ temp_gray[2];
assign temp_gray[3] = next_gray[8];
assign temp_gray[4] = next_gray[8] ^ temp_gray[2];
assign temp_gray[5] = next_gray[5] ^ next_gray[0];
assign temp_gray[6] = next_gray[9] ^ next_gray[3];
assign temp_gray[7] = next_gray[0] ^ next_gray[0];

endmodule

