module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;
  reg [3:0] tmp_reg;
  assign out = tmp_reg;
  always @(posedge clk or posedge rst)
  begin
    if (rst)
      tmp_reg <= 4'b0001;
    else
      tmp_reg <= 4'b0010;
  end
endmodule

