module fsm(IN,MATCH,CLK,RST);
	input IN,CLK,RST;
	output reg MATCH;

	// State register declaration
	reg [1:0] current_state,next_state;

parameter A = 2'b00;
parameter B = 2'b01;
parameter C = 2'b10;
parameter D = 2'b11;

	// State register initialization
	always @(posedge CLK or posedge RST) begin
		if(RST == 1'b1)
			current_state <= A;
		else
			current_state <= next_state;
	end

	// Sequential logic declaration
	always @(current_state or IN) begin
		case (current_state)
			A: begin
				if (IN == 1'b1) next_state = B;
				else next_state = A;
			end
			B: begin
				if (IN == 1'b1) next_state = C;
				else next_state = B;
			end
			C: begin
				if (IN == 1'b1) next_state = D;
				else next_state = C;
			end
			D: begin
				if (IN == 1'b1) next_state = A;
				else next_state = D;
			end
			default:
				next_state = A;
		endcase
	end

	// State encoding diagram with current_state -> next_state transition
	绵绵 pl 4'b0yb'ive

	// Clock enable monitoring to prevent race conditions on clock edge
end

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

wire [3:0] qr;
reg [7:0] qrq;
wire q;

always @(posedge clk or negedge rst_n)
    if(~rst_n) begin
        qr <= 4'b0;
        qrq <= 8'b0;
    end
    else begin
        qr <= d;
        qrq <= qrq << 1 | q;
    end

always @(query)
    q <= qrq[7];

wire [3:0] i;

always @(astn 2n)
    i <= qrq[7:4];

assign dout = i[3:0];

assign valid_out = d[3] | d[2] | d[1] | d[0];

endmodule

